import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mix, color, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    PlaneGeometry,
    BoxGeometry,
    Mesh,
    Texture,
    DoubleSide,
    SRGBColorSpace,
  } = THREE;

  const palette = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'hub-features-title';

  // ---- Atlas-derived aspect ratio ----
  const srcW = 512;
  const srcH = 320;
  const aspect = srcW / srcH;
  const planeWidth = 3.2;
  const planeHeight = planeWidth / aspect;

  // ---- Engineered gradient + grain backdrop plane (avoids flat-void) ----
  const backdropGeo = new PlaneGeometry(planeWidth, planeHeight, 1, 1);

  const placeholderTex = new Texture();
  const grainNode = texture(placeholderTex);

  const topColor = color(palette.surface);
  const bottomColor = color(palette.ink);
  const gradientNode = mix(bottomColor, topColor, uv().y);
  const grainInfluence = grainNode.rgb.sub(0.5).mul(0.12);
  const surfaceColorNode = gradientNode.add(grainInfluence);

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: surfaceColorNode,
    side: DoubleSide,
    transparent: false,
  });

  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, 0, -0.05);
  group.add(backdropMesh);

  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      tex.colorSpace = SRGBColorSpace;
      tex.wrapS = THREE.ClampToEdgeWrapping;
      tex.wrapT = THREE.ClampToEdgeWrapping;
      grainNode.value = tex;
      backdropMat.needsUpdate = true;
    })
    .catch(() => {
      /* texture optional — gradient still reads without grain */
    });

  // ---- Thin accent underline (sparing accent usage, extruded not flat) ----
  const accentGeo = new BoxGeometry(planeWidth * 0.42, 0.035, 0.035);
  const accentMat = new MeshBasicNodeMaterial({
    colorNode: color(palette.accent),
  });
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-planeWidth * 0.5 + planeWidth * 0.42 * 0.5 + 0.05, -planeHeight * 0.32, 0.03);
  group.add(accentMesh);

  // ---- Headline text via MSDF atlas ----
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? {
    text: 'Features',
    role: 'headline',
    typography: { fontSize: 96 },
  };

  const fontSize = headlineItem.typography?.fontSize ?? 96;
  const headlineText = ctx.fontAtlas.createText(headlineItem.text ?? 'Features', {
    fontSize,
    color: palette.paper,
    align: 'center',
  });
  headlineText.position.set(0, 0.05, 0.05);
  group.add(headlineText);

  // ---- Apply any configured cinematic primitives (none specified, but honor contract) ----
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const applyFn = ctx.primitives[prim.name];
    if (typeof applyFn === 'function') {
      const handle = applyFn(group, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- Entrance motion: weighted rise-in + settle (kept subtle per static-composition spec) ----
  const timelines = [];
  group.position.y += 0.4;
  const introTl = gsap.timeline();
  introTl.to(group.position, {
    y: group.position.y - 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });
  introTl.fromTo(
    group.scale,
    { x: 0.98, y: 0.98, z: 0.98 },
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
    0
  );
  timelines.push(introTl);

  // ---- Cleanup ----
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const handle of primitiveHandles) {
      handle?.timeline?.kill?.();
      handle?.cleanup?.();
    }
    backdropGeo.dispose();
    backdropMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    if (placeholderTex) placeholderTex.dispose();
    if (grainNode.value && grainNode.value.dispose) grainNode.value.dispose();
    if (headlineText.userData?.cleanup) headlineText.userData.cleanup();
  };

  return group;
}
